from collections import defaultdict
import sys

sys.setrecursionlimit(1000000)

def solve_cycles(n, adj):
    """Try to find k cycles with representative vertices"""
    k = sys.maxsize

    # Track which vertices are in any cycle
    cycle_vertices = set()
    cycles = []

    # DFS to find cycles
    stack = [(1, 0)]  # (current, parent)
    visited = {1}

    while stack:
        curr, parent = stack.pop()

        for neighbor in adj[curr]:
            if neighbor == parent:
                continue
            if neighbor in visited:
                # Found a cycle
                cycle = []
                temp = neighbor
                while temp != parent:
                    cycle.append(temp)
                    temp = adj[temp].index(parent) if parent in adj[temp] else temp
                cycle.append(curr if curr != parent else parent)
                cycles.append(cycle)
                for v in cycle:
                    cycle_vertices.add(v)

            else:
                visited.add(neighbor)
                stack.append((neighbor, curr))

    # Verify cycles have length not divisible by 3 and get representatives
    for cycle in cycles:
        length = len(cycle)
        if length < 3:
            continue
        if length % 3 != 0:
            # This cycle is valid
            # Find a representative (vertex not in other cycles)
            found_rep = False
            for v in cycle:
                if v not in cycle_vertices or not is_in_other_cycles(v, cycles, cycle):
                    found_rep = True
                    break

    return cycles


def is_in_other_cycles(v, all_cycles, current_cycle_idx):
    for i, cycle in enumerate(all_cycles):
        if i != current_cycle_idx and v in cycle:
            return True
    return False


def solution(input_str):
    data = input_str.strip().split('\n')
    if not data:
        return "-1"

    n, m, k = map(int, data[0].split())
    adj = defaultdict(list)

    for i in range(1, m + 1):
        v, u = map(int, data[i].split())
        adj[v].append(u)
        adj[u].append(v)

    target_path_len = k  # We need path length >= n/k, so floor(n/k) vertices

    # Try to find k cycles first
    def try_find_cycles():
        nonlocal k
        # Use DFS-based cycle finding
        found_cycles = []
        vertices_used = set()

        def dfs_find_cycles(start_node=1):
            nonlocal found_cycles, vertices_used
            if len(found_cycles) >= k:
                return

            visited = {start_node}
            stack = [(start_node, -1, [start_node])]  # (node, parent, path)

            while stack and len(found_cycles) < k:
                node, parent, path = stack.pop()

                for neighbor in adj[node]:
                    if neighbor == parent:
                        continue
                    if neighbor in visited:
                        # Found a cycle
                        if node in adj[parent]:
                            for v in path:
                                vertices_used.add(v)
                        found_cycles.append(path + [neighbor])
                    else:
                        visited.add(neighbor)
                        stack.append((neighbor, node, path + [neighbor]))

        dfs_find_cycles()

        # Verify and filter
        valid_cycles = []
        representative_cycles = []

        for cycle in found_cycles:
            length = len(cycle) - 1  # Last vertex is same as first
            if length < 3:
                continue
            if length % 3 != 0:
                # Find representative
                rep = cycle[0]
                in_other = False
                for other in representative_cycles:
                    if rep in other:
                        in_other = True
                        break
                if not in_other:
                    representative_cycles.append((cycle, rep))
                    valid_cycles.append(cycle)

        if len(valid_cycles) >= k:
            return valid_cycles[:k], [c[0] for c in representative_cycles[:k]]
        return None, None

    cycles, reps = try_find_cycles()

    if cycles and len(cycles) >= k:
        # Format output for Solving
        output = ["CYCLES"]
        for i, cycle in enumerate(cycles[:k]):
            cycle_len = len(cycle) - 1  # Last vertex repeats first
            output.append(str(cycle_len))
            cycle_str = cycle[0] if cycle[0] != cycle[-1] else ' '.join(map(str, cycle[:-1]))
            output.append(cycle_str)
        return '\n'.join(output)

    # Try to find a long path for Johnny
    target_len = (n + k - 1) // k

    def find_long_path():
        for start in range(1, n + 1):
            path = [start]
            path_set = {start}
            stack = (start, -1)

            # Iterative DFS to find path
            while stack and len(path) < target_len:
                node, parent = stack

                found = False
                for neighbor in adj[node]:
                    if neighbor != parent and neighbor not in path_set:
                        path.append(neighbor)
                        path_set.add(neighbor)
                        stack = (neighbor, node)
                        found = True
                        break

                if not found:
                    path.pop()
                    path_set.remove(stack[0])
                    stack = (next(iter(stack)), -1) if stack else None

            if len(path) >= target_len:
                return path[:target_len]

        return None

    path = find_long_path()
    if path:
        return f"PATH\n{len(path)}\n{' '.join(map(str, path))} \n"

    return "-1"


