def try_solving():
    """Try to satisfy Solving's requirements"""
    cycle_set = set()
    cycle_list = []

    def dfs(start, parent, path, visited):
        if len(cycle_list) >= _k:
            return True

        current = start
        for neighbor in _adj[current]:
            if neighbor == parent:
                continue
            if neighbor in visited:
                # Found cycle
                cycle = path + [neighbor]
                cycle_len = len(cycle) - 1
                if cycle_len >= 3 and cycle_len % 3 != 0:
                    cycle_list.append(cycle)
                    cycle_set.update(cycle)
                if len(cycle_list) >= _k:
                    return True
            else:
                if len(path) < 30:  # Limit recursion
                    visited.add(neighbor)
                    if dfs(neighbor, current, path + [neighbor], visited):
                        return True
                    visited.remove(neighbor)
        return False

    for i in range(1, n + 1):
        if len(cycle_list) >= _k:
            break
        if dfs(i, -1, [i], {i}):
            return True

    return len(cycle_list) >= _k


def solve_solving():
    """Generate output for Solving's solution"""
    cycles = [c for c in _find_cycles()[:_k]]
    reps = []
    for cycle in cycles:
        reps.append(cycle[0])

    output_lines = ["CYCLES"]
    for cycle in cycles:
        length = len(cycle) - 1
        output_lines.append(str(length))
        output_lines.append(' '.join(map(str, cycle)))

    return '\n'.join(output_lines)


def _find_cycles():
    """Find all valid cycles in graph"""
    visited_global = set()
    cycles = []

    def dfs(node, parent, path, visited):
        for neighbor in _adj[node]:
            if neighbor == parent:
                continue
            if neighbor in visited:
                if len(path) - 1 >= 3 and (len(path) - 1) % 3 != 0:
                    cycles.append(path + [neighbor])
            else:
                visited.add(neighbor)
                if len(path) < 25:
                    dfs(neighbor, node, path + [neighbor], visited)
                visited.remove(neighbor)

    for i in range(1, _n + 1):
        if i in visited_global:
            continue
        visited_global.add(i)
        dfs(i, -1, [i], {i})

    return cycles


def solve_johnny():
    """Try to find a long path for Johnny"""
    target_len = (_n + _k - 1) // _k

    def search(start):
        path = [start]
        visited = {start}

        while len(path) < target_len and path:
            u = path[-1]
            found = False
            for v in _adj[u]:
                if v not in visited:
                    path.append(v)
                    visited.add(v)
                    found = True
                    break
            if not found:
                path.pop()
                if visited:
                    visited.remove(path[-1])

        return None if len(path) < target_len else path

    for i in range(1, _n + 1):
        path = search(i)
        if path:
            return f"PATH\n{len(path)}\n{' '.join(map(str, path))} \n"

    return None


