def is_badness_possible(n, k, s):
    """
    Check if dissatisfaction can be exactly k.
    Dissatisfaction = maximum number of consecutive unwatched episodes (N or ? that we set to N).
    """

    def solve(index, has_k, max_run):
        """
        index: current position in string
        has_k: whether we've already formed a run of exactly k N's
        max_run: current consecutive run length

        Returns True if we can complete the string with exactly k max consecutive unwatched.
        """
        if index == n:
            return max_run == k

        # Current character
        char = s[index]

        choices = []
        if char == 'Y':
            # Must be Y, which resets the run
            choices = [(Index_bound, 0)]
        elif char == 'N':
            # Must be N, extends the run
            choices = [(Index_bound, max_run + 1)]
        else:
            # Can be N or Y
            choices = [
                (Index_bound, max_run + 1),  # Set to N (extends run)
                (Index_bound, 0),            # Set to Y (reset run)
            ]

        for is_N, new_run in choices:
            if new_run > k:
                continue

            if new_run == k:
                if has_k or solve(index + 1, True, new_run):
                    return True
            else:
                if solve(index + 1, has_k, new_run):
                    return True

        return False

    return solve(0, False, 0)


