class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)

    def find(self, x):
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        while self.parent[x] != root:
            self.parent[x], x = root, self.parent[x]
        return root

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return False
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1
        return True

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    if m == n - 1:
        return ''

    edges = []
    for i in range(m):
        parts = lines[i + 1].split()
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a, b, e))

    # Kruskal's algorithm to find MST
    uf = UnionFind(n)
    mst_count = 0
    mst_edges = []

    def find(x):
        root = x
        while uf.parent[root] != root:
            root = uf.parent[root]
        while uf.parent[x] != root:
            uf.parent[x], x = root, uf.parent[x]
        return root

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            uf.parent[px] = py if uf.rank[px] < uf.rank[py] else (px if uf.rank[py] < uf.rank[px] else px)
            if uf.rank[px] == uf.rank[py] and uf.parent[px] == py:
                uf.rank[px] += 1
            return True
        return False

    # Sort edges by weight
    sorted_edges = sorted(edges, key=lambda x: x[2])

    # Build MST adjacency list
    mst_adj = [[] for _ in range(n + 1)]

    for a, b, e in sorted_edges:
        if union(a, b):
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))
            mst_count += 1
            if mst_count == n - 1:
                break

    # BFS to build tree structure (depth, parent, max edge to parent)
    depth = [0] * (n + 1)
    parent = [0] * (n + 1)
    max_edge_to_parent = [0] * (n + 1)

    queue = deque([1])
    depth[1] = 0
    parent[1] = 0
    max_edge_to_parent[1] = 0

    for _ in queue:
        u = queue.popleft()
        for v, w in mst_adj[u]:
            if depth[v] == 0 and v != 1:
                depth[v] = depth[u] + 1
                parent[v] = u
                max_edge_to_parent[v] = w
                queue.append(v)

    # Binary lifting preprocessing
    LOG = 20
    up = [[0] * LOG for _ in range(n + 1)]
    max_to_up = [[0] * LOG for _ in range(n + 1)]

    for i in range(1, n + 1):
        up[i][0] = parent[i]
        max_to_up[i][0] = max_edge_to_parent[i]

    for j in range(1, LOG):
        for i in range(1, n + 1):
            if up[i][j - 1] != 0:
                up[i][j] = up[up[i][j - 1]][j - 1]
                max_to_up[i][j] = max(max_to_up[i][j - 1], max_to_up[up[i][j - 1]][j - 1])
            else:
                up[i][j] = 0

    def get_path_max(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        result = 0
        for j in range(LOG - 1, -1, -1):
            if depth[u] - (1 << j) >= depth[v]:
                result = max(result, max_to_up[u][j])
                u = up[u][j]

        if u == v:
            return result

        for j in range(LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                result = max(result, max_to_up[u][j], max_to_up[v][j])
                u = up[u][j]
                v = up[v][j]

        if u != v:
            result = max(result, max_to_up[u][0], max_to_up[v][0])

        return result

    # Mark MST edges
    mst_set = set()
    for a, b, e in sorted_edges[:mst_count]:
        mst_set.add((min(a, b), max(a, b)))

    # Process all edges in original input order
    result = []
    for a, b, e in edges:
        if (min(a, b), max(a, b)) not in mst_set:
            result.append(str(get_path_max(a, b)))

    return '\n'.join(result)


