import sys
from collections import deque

sys.setrecursionlimit(300000)

class Solution:
    def solve(self, input_str: str) -> str:
        if not input_str.strip():
            return ''

        lines = input_str.strip().split('\n')
        first_line = lines[0].split()
        n, m = int(first_line[0]), int(first_line[1])

        if m == n - 1:
            return ''

        edges = []
        for i in range(m):
            parts = lines[i + 1].split()
            a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
            edges.append((a, b, e))

        # Kruskal's MST
        sorted_edges = sorted(edges, key=lambda x: x[2])
        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        adj = [[] for _ in range(n + 1)]
        mst_count = 0

        for a, b, e in sorted_edges:
            root_a, root_b = find(a), find(b)
            if root_a != root_b:
                if rank[root_a] < rank[root_b]:
                    root_a, root_b = root_b, root_a
                parent[root_b] = root_a
                if rank[root_a] == rank[root_b]:
                    rank[root_a] += 1
                adj[a].append((b, e))
                adj[b].append((a, e))
                mst_count += 1
                if mst_count == n - 1:
                    break

        # BFS for tree properties
        depth = [0] * (n + 1)
        parent_array = [0] * (n + 1)
        max_edge_to_parent = [0] * (n + 1)
        visited = [False] * (n + 1)

        queue = deque([1])
        visited[1] = True
        parent_array[1] = 0

        while queue:
