                    depth[v] = depth[u] + 1
                    parent_array[v] = u
                    max_edge_to_parent[v] = w
                    queue.append(v)

        # Binary lifting
        LOG = 20
        up = [[0] * LOG for _ in range(n + 1)]
        max_to_up = [[0] * LOG for _ in range(n + 1)]

        for i in range(1, n + 1):
