def bfs_reachable(n, start_x, start_y, grid, target_lit):
    """BFS to find all lit cells reachable from start, respecting visibility"""
    if grid[start_x][start_y] == 1:
        target_lit.remove((start_x, start_y))
        return {target_lit}
    else:
        visited = set()
        queue = deque([(start_x, start_y)])
        visited.add((start_x, start_y))

        while queue:
            cx, cy = queue.popleft()

            # Check all directions
            for d_char in ['L', 'R', 'U', 'D']:
                dx, dy = grid_to_dirs[d_char]
                nx, ny = cx, cy

                valid_move = can_move(grid, cx, cy, dx, dy)

                if valid_move:
                    if 0 <= nx < n and 0 <= ny < n:
                        if (nx, ny) not in visited:
                            visited.add((nx, ny))
                            queue.append((nx, ny))

                # Check if we can enter here
                if grid[nx][ny] == 1:
                    pass

        return visited

grid_to_dirs = {'L': (0, -1), 'R': (0, 1), 'U': (-1, 0), 'D': (1, 0)}

def can_move(grid, cx, cy, dx, dy):
    """Check if we can move in direction (dx, dy) from (cx, cy)"""
    nx, ny = cx + dx, cy + dy
    while 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
        if grid[nx][ny] == 1:
            return True
        nx += dx
        ny += dy
    return False

