def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1"

    n = int(lines[0])
    centers = []
    for line in lines[1:n+1]:
        parts = line.strip().split()
        if len(parts) >= 2:
            xi, yi = map(float, parts[:2])
            centers.append((xi, yi))

    if n <= 2:
        return "-1"

    def dist(x1, y1, x2, y2):
        return math.hypot(x1-x2, y1-y2)

    def is_collinear(a, b, c):
        return abs((b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])) < 1e-9

    # Check if all centers are collinear
    if all(is_collinear(centers[i], centers[i+1], centers[i+2]) for i in range(n-2)):
        return "-1"

    best = 0.0

    # Check all pairs (midpoints)
    for i in range(n):
        for j in range(i+1, n):
            mx = (centers[i][0] + centers[j][0]) / 2
            my = (centers[i][1] + centers[j][1]) / 2
            dmin = min(dist(mx, my, centers[i][0], centers[i][1]),
                      dist(mx, my, centers[j][0], centers[j][1]),
                      min(dist(mx, my, centers[k][0], centers[k][1]) for k in range(n)))
            if dmin > best:
                best = dmin

    # Check all triples (circumcenters)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a, b, c = centers[i], centers[j], centers[k]
                D = 2 * (a[0]*(b[1] - c[1]) + b[0]*(c[1] - a[1]) + c[0]*(a[1] - b[1]))
                if abs(D) < 1e-9:
                    continue
                Ux = ((dist(a[0], a[1], b[0], b[1])**2) * (c[0] - a[0]) + 
                      (dist(b[0], b[1], c[0], c[1])**2) * (a[0] - b[0]) + 
                      (dist(c[0], c[1], a[0], a[1])**2) * (b[0] - c[0])) / (4 * D)
                Uy = ((dist(a[0], a[1], b[0], b[1])**2) * (c[1] - a[1]) + 
                      (dist(b[0], b[1], c[0], c[1])**2) * (a[1] - b[1]) + 
                      (dist(c[0], c[1], a[0], a[1])**2) * (b[1] - c[1])) / (4 * D)
                p = (Ux, Uy)
                min_d = min(dist(p[0], p[1], centers[i][0], centers[i][1]),
                           dist(p[0], p[1], centers[j][0], centers[j][1]),
                           dist(p[0], p[1], centers[k][0], centers[k][1]))
                # Also check distance to all other centers
                for m in range(n):
                    mn = dist(p[0], p[1], centers[m][0], centers[m][1])
                    if mn < min_d:
                        min_d = mn
                if min_d > best:
                    best = min_d

    # Random sampling across bounding box
    min_x = min(c[0] for c in centers)
    max_x = max(c[0] for c in centers)
    min_y = min(c[1] for c in centers)
    max_y = max(c[1] for c in centers)

    for _ in range(5000):
        x = random.uniform(min_x - 1, max_x + 1)
        y = random.uniform(min_y - 1, max_y + 1)
        dmin = min(dist(x, y, centers[i][0], centers[i][1]) for i in range(n))
        if dmin > best:
            best = dmin

    return f"{best:.6f}"

