def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True


def prime_factors_of(num):
    factors = []
    d = 2
    while d * d <= num:
        if num % d == 0:
            factors.append(d)
            while num % d == 0:
                num //= d
        d += 1
    if num > 1:
        factors.append(num)
    return factors


def check_primitive_root(b, n, prime_factors, p):
    # Check if b^(n/q) != 1 (mod p) for all prime factors q of n
    for q in prime_factors:
        if pow(b, n // q, p) == 1:
            return False
    return True

