    def consume():
        nonlocal pos
        ch = s[pos]
        pos += 1
        return ch

    def is_digit():
        c = peek()
        return c is not None and c.isdigit()

    def read_number():
        nonlocal pos
        start = pos
        while is_digit():
            consume()
        return s[start:pos]

    def parse_term():
        nonlocal pos
        num_str = read_number()
        num = int(num_str)

        # Check for range or repetition
        next_char = peek()

        if next_char == '-':
            consume()  # consume '-'
            r_str = read_number()
